import React, { useState, useEffect } from 'react';
import api from '../api';

function Login({ onLogin }) {
  const [volunteers, setVolunteers] = useState([]);
  const [selectedVolunteer, setSelectedVolunteer] = useState('');

  useEffect(() => {
    fetchVolunteers();
  }, []);

  const fetchVolunteers = async () => {
    try {
      const response = await api.get('/api/volunteers');
      if (response.data.success && Array.isArray(response.data.data)) {
        setVolunteers(response.data.data);
      } else {
        setVolunteers([]);
      }
    } catch (error) {
      console.error('Error fetching volunteers:', error);
      setVolunteers([]);
    }
  };

  const handleAdminLogin = () => {
    onLogin('admin', null);
  };

  const handleVolunteerLogin = () => {
    if (selectedVolunteer) {
      onLogin('volunteer', selectedVolunteer);
    } else {
      alert('Please select a volunteer');
    }
  };

  return (
    <div className="login-container">
      <div className="login-box">
        <h2>Event Volunteer System</h2>
        <p style={{ textAlign: 'center', marginBottom: '30px', color: '#666' }}>
          Select your role to continue
        </p>

        <div className="form-group">
          <label>Volunteer Login (Select Profile)</label>
          <select 
            value={selectedVolunteer}
            onChange={(e) => setSelectedVolunteer(e.target.value)}
            style={{ marginBottom: '10px' }}
          >
            <option value="">Select Volunteer</option>
            {(volunteers || []).map(volunteer => {
              const id = volunteer.id || volunteer._id;
              if (!id) return null;
              return (
                <option key={id} value={String(id)}>
                  {volunteer.name} - {volunteer.email}
                </option>
              );
            })}
          </select>
        </div>

        <div className="role-buttons">
          <button 
            className="role-button admin" 
            onClick={handleAdminLogin}
          >
            Admin Login
          </button>
          <button 
            className="role-button volunteer" 
            onClick={handleVolunteerLogin}
            disabled={!selectedVolunteer}
          >
            Volunteer Login
          </button>
        </div>

        <p style={{ textAlign: 'center', marginTop: '20px', fontSize: '12px', color: '#999' }}>
          Demo Mode - No password required
        </p>
      </div>
    </div>
  );
}

export default Login;
